/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

# Core Exo APIs.
from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable blocking factor for the inner j loop. This can be adjusted
# to fit a particular cache hierarchy without changing the C interface.
J_BLOCK_SIZE = 32


@proc
def kernel_jacobi_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points [1 : n-1), so n must be > 2.
    assert n > 2

    for t in seq(0, tsteps):
        # ------------------------------------------------------------------
        # First sweep: update B from A.
        # Each (i, j) in B depends only on a 5-point stencil in A.
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                B[i, j] = 0.2 * (
                    A[i, j]
                    + A[i, j - 1]
                    + A[i, j + 1]
                    + A[i + 1, j]
                    + A[i - 1, j]
                )

        # ------------------------------------------------------------------
        # Second sweep: update A from B.
        # Each (i, j) in A depends only on a 5-point stencil in B.
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                A[i, j] = 0.2 * (
                    B[i, j]
                    + B[i, j - 1]
                    + B[i, j + 1]
                    + B[i + 1, j]
                    + B[i - 1, j]
                )


# ---------------------------------------------------------------------------
# Schedule for kernel_jacobi_2d
#
# 1. Parallelize the spatial loops over i in both sweeps.
#    These loops are embarrassingly parallel: each (i, j) update writes
#    a unique cell and reads only from the opposite array (A->B, then B->A).
#
# 2. Block the inner j loops to improve cache locality along rows. The
#    blocking factor J_BLOCK_SIZE is a Python constant, so it can be tuned
#    per architecture without changing the C signature of the kernel.
# ---------------------------------------------------------------------------

def schedule_kernel_jacobi_2d(p):
    # ---- Parallelize spatial loops over i (first sweep: B update) ----
    t_loop = p.find_loop("t")
    # First 'i' loop inside the time loop: updates B from A.
    i_b = t_loop.body().find_loop("i")
    p = parallelize_loop(p, i_b)

    # ---- Parallelize spatial loops over i (second sweep: A update) ----
    # Re-find the time loop and then get the second 'i' loop (A update).
    t_loop = p.find_loop("t")
    i_a = t_loop.body().find_loop("i #1")
    p = parallelize_loop(p, i_a)

    # ---- Block the j loop in the first sweep (B update) ----
    # This creates a two-level j loop: jo (block index) and ji (intra-block).
    t_loop = p.find_loop("t")
    i_b = t_loop.body().find_loop("i")
    j_b = i_b.body().find_loop("j")
    p = divide_loop(p, j_b, J_BLOCK_SIZE, ("jo", "ji"), tail="guard")

    # ---- Block the j loop in the second sweep (A update) ----
    t_loop = p.find_loop("t")
    i_a = t_loop.body().find_loop("i #1")
    j_a = i_a.body().find_loop("j")
    p = divide_loop(p, j_a, J_BLOCK_SIZE, ("jo", "ji"), tail="guard")

    # Clean up expressions and guards after the transformations.
    p = simplify(p)

    return p


# Apply the schedule so that the exported procedure name
# 'kernel_jacobi_2d' refers to the optimized version.
kernel_jacobi_2d = schedule_kernel_jacobi_2d(kernel_jacobi_2d)
EXO END
