kernel_jacobi_2d_opt = divide_loop(
    kernel_jacobi_2d_opt,
    kernel_jacobi_2d_opt.find_loop("j #1"),  # j-loop of the second sweep
    J_BLOCK,
    ("jo1", "ji1"),
    tail="guard",
)

