kernel_jacobi_2d_opt = divide_loop(
    kernel_jacobi_2d_opt,
    kernel_jacobi_2d_opt.find_loop("i"),  # remaining i-loop is the first sweep
    I_BLOCK,
    ("io0", "ii0"),
    tail="guard",
)

