from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# ---------------------------------------------------------------------------
# Base Jacobi-2D kernel
# ---------------------------------------------------------------------------
# We write the stencil using zero-based interior indices (0 .. n-3) and add
# +1 when indexing the physical arrays. This keeps loop bounds in the
# canonical [0, hi) form that Exo's tiling primitives expect, while still
# updating exactly the interior points [1 .. n-2] in both dimensions.
@proc
def jacobi_2d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points, so n must be > 2.
    assert n > 2

    for t in seq(0, tsteps):
        # Jacobi sweep: A -> B
        for i in seq(0, n - 2):          # logical i in [0 .. n-3]
            for j in seq(0, n - 2):      # logical j in [0 .. n-3]
                # Physical indices are (i+1, j+1) in the original formulation.
                B[i + 1, j + 1] = 0.2 * (
                    A[i + 1, j + 1]      # center
                    + A[i + 1, j]        # left
                    + A[i + 1, j + 2]    # right
                    + A[i + 2, j + 1]    # down
                    + A[i,     j + 1]    # up
                )

        # Jacobi sweep: B -> A
        for i in seq(0, n - 2):
            for j in seq(0, n - 2):
                A[i + 1, j + 1] = 0.2 * (
                    B[i + 1, j + 1]
                    + B[i + 1, j]
                    + B[i + 1, j + 2]
                    + B[i + 2, j + 1]
                    + B[i,     j + 1]
                )


